// Скрипт печатает ход работы в stderr, а итог — последней строкой stdout: RESULT:{...}
const out = $input.first().json;
const lines = String(out.stdout || '').split(/\r?\n/).filter(Boolean);
const line = [...lines].reverse().find((l) => l.startsWith('RESULT:'));
if (!line) {
  throw new Error('Скрипт не вернул итог. Код выхода ' + out.exitCode + '. ' + String(out.stderr || '').slice(-600));
}
const r = JSON.parse(line.slice('RESULT:'.length));
if (!r.ok) throw new Error(r['ошибка'] || 'не удалось');
return [{ json: r }];

const r = $('Разобрать итог').first().json;
const out = { в_очереди: r['в_очереди'] };
out.очередь = r['очередь'] && r['очередь'].length ? r['очередь'] : 'пусто — поставьте товару тег reshoot в админке';
return [{ json: out }];
